import json


def read_json(path: str) -> dict:
    with open(path) as f:
        return json.load(f)


def load_settings(path: str) -> dict:
    # Settings files are expected to always contain a JSON object; a top-level
    # array or scalar would be valid JSON but not a usable settings dict.
    return read_json(path)

